                fill_buf[fill_count] = fill_src[copied];
                ++fill_count;
                ++copied;
              }
              parsed_specs.fill = basic_string_view<Char>(
                  spec_it, detail::to_unsigned(align_pos - spec_it));
              spec_it = align_pos + 1;
            } else {
              ++spec_it;
            }
            parsed_specs.align = parsed_align;
            break;
          } else if (align_pos == spec_it) {
            break;
          }
          align_pos = spec_it;
        }

        if (parsed_ok) {
          if (spec_it != spec_end) {
            auto sign_ch = detail::to_ascii(*spec_it);
            if (sign_ch == '+') {
              parsed_sign = sign::plus;
              ++spec_it;
            } else if (sign_ch == '-') {
              parsed_sign = sign::minus;
              ++spec_it;
            } else if (sign_ch == ' ') {
              parsed_sign = sign::space;
              ++spec_it;
            }
            parsed_specs.sign = parsed_sign;
          }

          if (spec_it != spec_end) {
            if (*spec_it == '#') {
              parsed_alt = true;
              parsed_specs.alt = true;
              ++spec_it;
            }
          }

          if (spec_it != spec_end) {
            if (*spec_it == '0') {
              saw_zero_flag = true;
              if (parsed_specs.align == align::none) {
                parsed_specs.align = align::numeric;
                parsed_align = align::numeric;
              }
              parsed_specs.fill[0] = Char('0');
              fill_buf[0] = Char('0');
              fill_count = 1;
              ++spec_it;
            }
          }

          if (spec_it != spec_end) {
            if (*spec_it == '{') {
              saw_dynamic_width = true;
              ++spec_it;
              while (spec_it != spec_end) {
                if (*spec_it == '}') break;
                ++spec_it;
              }
              if (spec_it == spec_end) {
                parsed_ok = false;
                if (!spec_error) spec_error = "invalid format string";
              } else {
                ++spec_it;
              }
            } else if (*spec_it >= '0') {
              if (*spec_it <= '9') {
                int_begin = spec_it;
                parsed_width =
                    detail::parse_nonnegative_int(int_begin, spec_end, -1);
                spec_it = int_begin;
                if (parsed_width != -1) {
                  parsed_specs.width = parsed_width;
                } else {
                  parsed_ok = false;
                  if (!spec_error) spec_error = "number is too big";
                }
              }
            }
          }

          if (parsed_ok) {
            if (spec_it != spec_end) {
              if (*spec_it == '.') {
                ++spec_it;
                if (spec_it != spec_end) {
                  if (*spec_it == '{') {
                    saw_dynamic_precision = true;
                    ++spec_it;
                    while (spec_it != spec_end) {
                      if (*spec_it == '}') break;
                      ++spec_it;
                    }
                    if (spec_it == spec_end) {
                      parsed_ok = false;
                      if (!spec_error) spec_error = "invalid format string";
                    } else {
                      ++spec_it;
                    }
                  } else if (*spec_it >= '0') {
                    if (*spec_it <= '9') {
                      int_begin = spec_it;
                      parsed_precision = detail::parse_nonnegative_int(
                          int_begin, spec_end, -1);
                      spec_it = int_begin;
                      if (parsed_precision != -1) {
                        parsed_specs.precision = parsed_precision;
                      } else {
                        parsed_ok = false;
                        if (!spec_error) spec_error = "number is too big";
                      }
                    }
                  } else {
                    parsed_ok = false;
                    if (!spec_error)
                      spec_error = "missing precision specifier";
                  }
                } else {
                  parsed_ok = false;
                  if (!spec_error) spec_error = "missing precision specifier";
                }
              }
            }
          }

          if (parsed_ok) {
            if (spec_it != spec_end) {
              if (*spec_it == 'L') {
                parsed_localized = true;
                parsed_specs.localized = true;
                ++spec_it;
              }
            }
          }

          if (parsed_ok) {
            if (spec_it != spec_end) {
              if (*spec_it != '}') {
                parsed_type = detail::parse_presentation_type(*spec_it);
                parsed_specs.type = parsed_type;
                ++spec_it;
                if (parsed_type == presentation_type::none) {
                  parsed_ok = false;
                  if (!spec_error) spec_error = "invalid type specifier";
                }
              }
            }
          }

          if (parsed_ok) {
            auto eh = ctx.error_handler();
            if (arg_type == detail::type::char_type) {
              detail::check_char_specs(parsed_specs, eh);
            } else if (arg_type == detail::type::bool_type) {
              if (parsed_specs.type != presentation_type::none &&
                  parsed_specs.type != presentation_type::string)
                detail::check_int_type_spec(parsed_specs.type, eh);
            } else if (detail::is_integral_type(arg_type)) {
              detail::check_int_type_spec(parsed_specs.type, eh);
            } else if (detail::is_arithmetic_type(arg_type)) {
              detail::parse_float_type_spec(parsed_specs, eh);
            }
          }
        }
      }
    }

    parsed_specs.width = parsed_width;
    parsed_specs.precision = parsed_precision;
    parsed_specs.type = parsed_type;
    parsed_specs.align = parsed_align;
    parsed_specs.sign = parsed_sign;
    parsed_specs.alt = parsed_alt;
    parsed_specs.localized = parsed_localized;
    if (saw_zero_flag) {
      if (parsed_specs.align == align::none)
        parsed_specs.align = align::numeric;
    }
    parsed_specs.fill = basic_string_view<Char>(fill_buf, fill_count);
    if (saw_dynamic_width) parsed_specs.width_ref = detail::arg_ref<Char>();
    if (saw_dynamic_precision)
      parsed_specs.precision_ref = detail::arg_ref<Char>();
    if (spec_error) {
      if (report_errors) ctx.on_error(spec_error);
    }
    return underlying_.parse(ctx);
  }

  template <typename R, class FormatContext>
  auto format(R&& range, FormatContext& ctx) const -> decltype(ctx.out()) {
    detail::range_mapper<buffer_context<Char>> mapper;
    auto out = ctx.out();
    out = detail::copy_str<Char>(opening_bracket_, out);
    int i = 0;
    auto it = detail::range_begin(range);
    auto end = detail::range_end(range);
    for (; it != end; ++it) {
      if (i > 0) out = detail::copy_str<Char>(separator_, out);
      ;
      ctx.advance_to(out);
      out = underlying_.format(mapper.map(*it), ctx);
      ++i;
    }
    out = detail::copy_str<Char>(closing_bracket_, out);
    return out;
  }
};

enum class range_format { disabled, map, set, sequence, string, debug_string };

namespace detail {
template <typename T> struct range_format_kind_ {
  static constexpr auto value = std::is_same<range_reference_type<T>, T>::value
                                    ? range_format::disabled
                                : is_map<T>::value ? range_format::map
                                : is_set<T>::value ? range_format::set
                                                   : range_format::sequence;
};

template <range_format K, typename R, typename Char, typename Enable = void>
struct range_default_formatter;

template <range_format K>
using range_format_constant = std::integral_constant<range_format, K>;

template <range_format K, typename R, typename Char>
struct range_default_formatter<
    K, R, Char,
    enable_if_t<(K == range_format::sequence || K == range_format::map ||
                 K == range_format::set)>> {
  using range_type = detail::maybe_const_range<R>;
  range_formatter<detail::uncvref_type<range_type>, Char> underlying_;

  FMT_CONSTEXPR range_default_formatter() { init(range_format_constant<K>()); }

  FMT_CONSTEXPR void init(range_format_constant<range_format::set>) {
    underlying_.set_brackets(detail::string_literal<Char, '{'>{},
                             detail::string_literal<Char, '}'>{});
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::map>) {
    underlying_.set_brackets(detail::string_literal<Char, '{'>{},
                             detail::string_literal<Char, '}'>{});
    underlying_.underlying().set_brackets({}, {});
    underlying_.underlying().set_separator(
        detail::string_literal<Char, ':', ' '>{});
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::sequence>) {}

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return underlying_.parse(ctx);
  }

  template <typename FormatContext>
  auto format(range_type& range, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    return underlying_.format(range, ctx);
  }
};
}  // namespace detail

template <typename T, typename Char, typename Enable = void>
struct range_format_kind
    : conditional_t<
          is_range<T, Char>::value, detail::range_format_kind_<T>,
          std::integral_constant<range_format, range_format::disabled>> {};

